Lemma rmalloc_fp_cases_ER stE mE lo sp a :
  rmrep stE mE -> rmalloc_fp st0 stE lo sp a -> lo <= a < sp \/ a < hceil.
Proof. try hcb. try hsb.
  intros (WF2 & _) H. pose proof WF2 as (_ & WR2 & _). pose proof MR as ((RS1 & _) & _).
  hcb; unfold Malloc.alloc_ceiling, Decode.alloc_ceiling in *.
  destruct H as [[H|[H|[H|(rid & r & Hr & _ & Ha)]]]|[(rid & r & Hr & _ & Ha)|[(g & b & r & i & _ & Hr & _ & _ & _ & Ha & _)|[(b & gh & r & _ & Hr & _ & Ha & _)|[FC FR]]]]].
  all: try pose proof (rfresh_below st0 a (conj FC FR) ltac:(rewrite <- (mrel_reserved _ _ (er_mrel _ _ ER)); exact RS1)) as FC'.
  - left; exact H.
  - right. rewrite unsigned_lit in H by lia. lia.
  - right. unfold RCTX in H. lia.
  - right. destruct (WR2 rid r Hr) as (_ & _ & _ & RC & _). hcb; unfold Malloc.alloc_ceiling, Decode.alloc_ceiling in RC. lia.
  - right. destruct (WR2 rid r Hr) as (_ & _ & _ & RC & _). hcb; unfold Malloc.alloc_ceiling, Decode.alloc_ceiling in RC. lia.
  - right. destruct (rst0_region (fst b) r Hr) as (_ & RC & _). hcb; unfold Malloc.alloc_ceiling, Decode.alloc_ceiling in RC. lia.
  - right. destruct (rst0_region (fst b) r Hr) as (_ & RC & _). hcb; unfold Malloc.alloc_ceiling, Decode.alloc_ceiling in RC. lia.
